// Recursively walk the Drive folder tree under FOLDER_ID using BFS and
// return every Google Doc + Sheet anywhere in the tree (not just direct
// children). Uses this node's attached Drive OAuth2 credential.
//
// Output shape matches the old HTTP node: { files: [...] } so Plan & Filter
// keeps working without changes.

const FOLDER_ID   = '1iiu1PXh1LilB7B9mmJ2ZBLZIuMMGJ8Kd';
const DOC_MIME    = 'application/vnd.google-apps.document';
const SHEET_MIME  = 'application/vnd.google-apps.spreadsheet';
const FOLDER_MIME = 'application/vnd.google-apps.folder';
const MAX_FOLDERS = 2000; // safety cap so a pathological tree can't run forever

async function driveList(qs) {
  return await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleDriveOAuth2Api',
    {
      method: 'GET',
      url: 'https://www.googleapis.com/drive/v3/files',
      qs,
      json: true,
      timeout: 30000
    }
  );
}
const boundList = driveList.bind(this);

const visited     = new Set();
const queue       = [FOLDER_ID];
const files       = [];
const skippedDirs = []; // folders we couldn't read -- surfaced for debugging

while (queue.length && visited.size < MAX_FOLDERS) {
  const folderId = queue.shift();
  if (visited.has(folderId)) continue;
  visited.add(folderId);

  let pageToken;
  do {
    let resp;
    try {
      resp = await boundList({
        q: `'${folderId}' in parents and trashed = false`,
        fields: 'nextPageToken,files(id,name,mimeType,modifiedTime,webViewLink,parents)',
        pageSize: 1000,
        pageToken,
        supportsAllDrives: 'true',
        includeItemsFromAllDrives: 'true'
      });
    } catch (e) {
      skippedDirs.push({ folder_id: folderId, error: String(e.message || e).slice(0, 200) });
      resp = { files: [] };
      pageToken = undefined;
      break;
    }

    for (const f of (resp.files || [])) {
      if (f.mimeType === FOLDER_MIME) {
        if (!visited.has(f.id)) queue.push(f.id);
      } else if (f.mimeType === DOC_MIME || f.mimeType === SHEET_MIME) {
        files.push(f);
      }
    }
    pageToken = resp.nextPageToken;
  } while (pageToken);
}

return [{
  json: {
    files,
    folders_walked: visited.size,
    folders_skipped: skippedDirs
  }
}];

// Plan & Filter
// Combine outputs from Whoami / Folder Meta / List Children, query Supabase
// for already-indexed files, and emit ONE ITEM PER FILE that needs (re)indexing.
// If the folder isn't accessible, emit a single diagnostic item so the run
// stops with a useful error instead of silently doing nothing.
//
// ----- CONFIG (only Supabase needed here) ---------------------
const SUPABASE_URL = 'https://xirmohenadyurcwlnchy.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Inhpcm1vaGVuYWR5dXJjd2xuY2h5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3OTQxMDU4MCwiZXhwIjoyMDk0OTg2NTgwfQ.WcUpZXQHJ57z0Qm8Cd-V0oYl2KzHwbae-Qv4L9e1w_8';
const FOLDER_ID    = '1iiu1PXh1LilB7B9mmJ2ZBLZIuMMGJ8Kd';
// --------------------------------------------------------------

const whoamiResp     = (($('Drive: Whoami').first()       || {}).json) || {};
const folderMetaResp = (($('Drive: Folder Meta').first()  || {}).json) || {};
const listResp       = (($('Drive: Walk Tree').first()    || {}).json) || {};

const connectedUser = whoamiResp.user || null;

// Folder visibility check -- if folder meta came back with an error shape, bail
const folderOk = folderMetaResp && folderMetaResp.id === FOLDER_ID;
if (!folderOk) {
  return [{ json: {
    __halt: true,
    diagnostic: 'Folder is not visible to the connected Drive account.',
    connected_as: connectedUser,
    folder_id_used: FOLDER_ID,
    folder_meta_response: folderMetaResp,
    fix_options: [
      connectedUser && connectedUser.emailAddress ? `Share the folder with ${connectedUser.emailAddress}` : 'Share the folder with the connected account',
      'OR reconnect the Drive credential using the account that owns the folder',
      'OR verify the folder ID matches the URL'
    ]
  }}];
}

const files = (listResp && listResp.files) || [];
if (files.length === 0) {
  return [{ json: {
    __halt: true,
    diagnostic: 'Folder is visible but no Google Docs or Sheets were found anywhere in the tree.',
    connected_as: connectedUser,
    folder_info: folderMetaResp,
    folders_walked: listResp.folders_walked,
    folders_skipped: listResp.folders_skipped,
    fix_options: [
      'Confirm the folder (or its subfolders) actually contains .gdoc/.gsheet files -- PDFs, slides, images, and non-Google formats are intentionally skipped',
      'If folders_skipped is non-empty, the credential lacks permission on those subfolders -- share them with the connected account'
    ]
  }}];
}

// Query Supabase for already-indexed files
let indexedMap = new Map();
try {
  const indexedRows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/marketing_doc_files?select=drive_file_id,modified_time`,
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}` },
    json: true, timeout: 30000
  });
  for (const r of (indexedRows || [])) indexedMap.set(r.drive_file_id, r.modified_time);
} catch (e) {
  return [{ json: {
    __halt: true,
    error: 'Could not query Supabase for indexed state',
    detail: String(e.message || e).slice(0, 300),
    connected_as: connectedUser
  }}];
}

const changed = files.filter(f => {
  const last = indexedMap.get(f.id);
  if (!last) return true;
  return new Date(f.modifiedTime).getTime() > new Date(last).getTime();
});

if (changed.length === 0) {
  return [{ json: {
    __halt: true,
    diagnostic: 'Folder visible, files found, but nothing has changed since the last index.',
    connected_as: connectedUser,
    total_in_folder: files.length,
    indexed_so_far: indexedMap.size
  }}];
}

// Emit one item per file to (re)index
return changed.map(f => ({
  json: {
    __halt: false,
    drive_file_id: f.id,
    file_name:     f.name,
    file_url:      f.webViewLink || `https://drive.google.com/file/d/${f.id}/view`,
    mime_type:     f.mimeType,
    modified_time: f.modifiedTime,
    export_mime:   f.mimeType === 'application/vnd.google-apps.document' ? 'text/plain' : 'text/csv',
    connected_as:  connectedUser,
    total_in_folder: files.length
  }
}));

// Embed & Upsert
// For each file (one item per input), chunk the exported text, embed each chunk
// via OpenAI, then delete-then-insert into Supabase. Returns one item per file
// reporting success/failure.
//
// ----- CONFIG ------------------------------------------------
const OPENAI_API_KEY = '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';
const SUPABASE_URL   = 'https://xirmohenadyurcwlnchy.supabase.co';
const SUPABASE_KEY   = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Inhpcm1vaGVuYWR5dXJjd2xuY2h5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3OTQxMDU4MCwiZXhwIjoyMDk0OTg2NTgwfQ.WcUpZXQHJ57z0Qm8Cd-V0oYl2KzHwbae-Qv4L9e1w_8';
const EMBEDDING_MODEL = 'text-embedding-3-small';
const CHUNK_TOKENS    = 800;
const CHUNK_OVERLAP   = 100;
const EMBED_BATCH     = 16;
const INSERT_BATCH    = 100;
// --------------------------------------------------------------

function chunkText(text, fileName) {
  const charSize    = CHUNK_TOKENS  * 4;
  const charOverlap = CHUNK_OVERLAP * 4;
  const cleaned = String(text || '').replace(/\u0000/g, '').replace(/\r\n/g, '\n').trim();
  if (!cleaned) return [];
  const out = [];
  let i = 0;
  while (i < cleaned.length) {
    let end = Math.min(i + charSize, cleaned.length);
    if (end < cleaned.length) {
      const win = cleaned.slice(Math.max(end - 200, i + 1), end + 200);
      const m = win.search(/\n\n|\. /);
      if (m !== -1) end = Math.max(end - 200, i + 1) + m;
    }
    const piece = cleaned.slice(i, end).trim();
    if (piece) out.push(`[Source: ${fileName}]\n${piece}`);
    if (end >= cleaned.length) break;
    i = Math.max(end - charOverlap, i + 1);
  }
  return out;
}

async function embedBatch(texts) {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/embeddings',
    headers: {
      Authorization: `Bearer ${OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: { input: texts, model: EMBEDDING_MODEL },
    json: true, timeout: 90000
  });
  return (resp.data || []).map(d => d.embedding);
}

async function deleteChunks(fileId) {
  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `${SUPABASE_URL}/rest/v1/marketing_doc_chunks?drive_file_id=eq.${encodeURIComponent(fileId)}`,
    headers: {
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
      Prefer: 'return=minimal'
    },
    timeout: 30000
  });
}

async function insertChunksBatch(rows) {
  for (let i = 0; i < rows.length; i += INSERT_BATCH) {
    const slice = rows.slice(i, i + INSERT_BATCH);
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/marketing_doc_chunks`,
      headers: {
        apikey: SUPABASE_KEY,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal'
      },
      body: slice,
      json: true, timeout: 90000
    });
  }
}

const items = $input.all();
const results = [];

for (const item of items) {
  const meta = item.json || {};
  const fileId   = meta.drive_file_id;
  const fileName = meta.file_name;
  const fileUrl  = meta.file_url;
  const mimeType = meta.mime_type;
  const modified = meta.modified_time;

  // The Drive Export node attaches the file body. When responseFormat=text,
  // n8n puts the body under either `data` or a single key in the json; if the
  // request fails it may be under `body` or empty. Be lenient.
  let text = '';
  if (typeof meta.data === 'string')      text = meta.data;
  else if (typeof meta.body === 'string') text = meta.body;
  else if (typeof meta === 'string')      text = meta;
  else {
    // Last resort: stringify whatever non-meta keys are present
    const extra = { ...meta };
    ['drive_file_id','file_name','file_url','mime_type','modified_time','export_mime','connected_as','total_in_folder','__halt'].forEach(k => delete extra[k]);
    const k = Object.keys(extra)[0];
    if (k && typeof extra[k] === 'string') text = extra[k];
  }

  if (!text.trim()) {
    results.push({ json: { file_id: fileId, file_name: fileName, ok: false, error: 'export returned empty body' }});
    continue;
  }

  try {
    const chunks = chunkText(text, fileName);
    if (!chunks.length) {
      results.push({ json: { file_id: fileId, file_name: fileName, ok: false, error: 'no chunks produced' }});
      continue;
    }

    const embeddings = [];
    for (let i = 0; i < chunks.length; i += EMBED_BATCH) {
      const batch = chunks.slice(i, i + EMBED_BATCH);
      const vecs  = await embedBatch.call(this, batch);
      if (vecs.length !== batch.length) throw new Error('embedding count mismatch');
      embeddings.push(...vecs);
    }

    const rows = chunks.map((content, idx) => ({
      drive_file_id: fileId,
      file_name:     fileName,
      file_url:      fileUrl,
      mime_type:     mimeType,
      modified_time: modified,
      chunk_index:   idx,
      content,
      embedding:     embeddings[idx]
    }));

    await deleteChunks.call(this, fileId);
    await insertChunksBatch.call(this, rows);
    results.push({ json: { file_id: fileId, file_name: fileName, ok: true, chunks: chunks.length }});
  } catch (e) {
    results.push({ json: { file_id: fileId, file_name: fileName, ok: false, error: String(e.message || e).slice(0, 240) }});
  }
}

return results;

// Aggregate per-file results into one final summary.
const results = $input.all().map(i => i.json || {});
const connected = (($('Plan & Filter').first() || {}).json || {}).connected_as || null;
const totalInFolder = (($('Plan & Filter').first() || {}).json || {}).total_in_folder || 0;

const indexed = results.filter(r => r.ok);
const failed  = results.filter(r => !r.ok);

return [{
  json: {
    total_in_folder: totalInFolder,
    attempted:       results.length,
    indexed:         indexed.length,
    failed:          failed.length,
    errors:          failed.map(f => ({ file: f.file_name, error: f.error })),
    indexed_files:   indexed.map(f => ({ file: f.file_name, chunks: f.chunks })),
    connected_as:    connected,
    finished_at:     new Date().toISOString()
  }
}];
